"use client"

import { useState, useEffect, Suspense } from "react"
import Header from "@/components/header"
import Footer from "@/components/footer"
import { Heart, ShoppingCart, Loader2 } from "lucide-react"
import { useSearchParams } from "next/navigation"
import { supabase } from "@/lib/supabase"
import Link from "next/link"

interface Product {
  id: string
  name: string
  category: string
  price: number
  originalPrice?: number
  image: string
  rating: number
  reviews: number
  badge?: string
  ageGroup?: string
}

function ProductsContent() {
  const searchParams = useSearchParams()
  const urlSearch = searchParams.get("search") || ""

  const [products, setProducts] = useState<Product[]>([])
  const [loading, setLoading] = useState(true)
  const [wishlist, setWishlist] = useState<string[]>([])
  const [sortBy, setSortBy] = useState("popular")

  // Filters
  const [selectedCategory, setSelectedCategory] = useState("All")
  const [selectedAge, setSelectedAge] = useState<string | null>(null)
  const [showSaleOnly, setShowSaleOnly] = useState(false)

  const [categoriesList, setCategoriesList] = useState<string[]>(["All"])

  // Sync URL Params to State
  useEffect(() => {
    const catParam = searchParams.get("category")
    const ageParam = searchParams.get("age")
    const saleParam = searchParams.get("sale")

    if (catParam) setSelectedCategory(catParam)
    else setSelectedCategory("All")

    setSelectedAge(ageParam) // null if not present
    setShowSaleOnly(saleParam === "true")
  }, [searchParams])

  // Fetch Categories for Sidebar
  useEffect(() => {
    async function fetchCategories() {
      const { data } = await supabase.from('categories').select('name')
      if (data) {
        setCategoriesList(["All", ...data.map(c => c.name)])
      }
    }
    fetchCategories()
  }, [])

  // Fetch Products
  useEffect(() => {
    async function fetchProducts() {
      setLoading(true)

      // Base Query
      let query = supabase
        .from('products')
        .select('*, category:categories(name)')

      // Apply Search (Server-side)
      if (urlSearch) {
        query = query.ilike('name', `%${urlSearch}%`)
      }

      // Apply Sort (Server-side)
      switch (sortBy) {
        case 'price-low':
          query = query.order('price', { ascending: true })
          break
        case 'price-high':
          query = query.order('price', { ascending: false })
          break
        case 'newest':
          query = query.order('created_at', { ascending: false })
          break
        default:
          query = query.order('created_at', { ascending: false })
      }

      const { data, error } = await query

      if (error) {
        console.error('Error fetching products:', error)
        setLoading(false)
        return
      }

      if (data) {
        // Map to UI Model
        let mappedProducts = data.map((p: any) => ({
          id: p.id,
          name: p.name,
          category: p.category?.name || "General",
          price: p.price,
          originalPrice: p.sale_price || undefined,
          image: p.images?.[0] || "",
          rating: 4.5, // Placeholder
          reviews: 0,
          badge: p.is_new ? "New" : (p.sale_price ? "Sale" : undefined),
          ageGroup: p.age_group
        }))

        // Client-side Filtering

        // 1. Category
        if (selectedCategory !== "All") {
          mappedProducts = mappedProducts.filter((p: Product) => p.category === selectedCategory)
        }

        // 2. Age Group
        if (selectedAge) {
          mappedProducts = mappedProducts.filter((p: Product) => p.ageGroup && p.ageGroup.includes(selectedAge))
        }

        // 3. Sale Items Only
        if (showSaleOnly) {
          mappedProducts = mappedProducts.filter((p: Product) => p.originalPrice && p.price < p.originalPrice)
        }

        setProducts(mappedProducts)
      }
      setLoading(false)
    }

    fetchProducts()
  }, [selectedCategory, selectedAge, showSaleOnly, sortBy, urlSearch])

  const toggleWishlist = (id: string) => {
    setWishlist((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]))
  }

  return (
    <div className="w-full min-h-screen bg-background text-foreground">
      <Header />

      {/* Premium Banner */}
      <div className="bg-gradient-to-r from-primary to-secondary py-12 px-4">
        <div className="max-w-6xl mx-auto">
          <h1 className="text-4xl font-bold text-primary-foreground mb-2">
            {urlSearch
              ? `Search Results for "${urlSearch}"`
              : selectedCategory !== "All"
                ? selectedCategory
                : showSaleOnly
                  ? "Exclusive Offers"
                  : selectedAge
                    ? `Shop by Age: ${selectedAge}`
                    : "Shop All Products"
            }
          </h1>
          <p className="text-primary-foreground/80">Discover our complete collection of toys, games, and stationery</p>
        </div>
      </div>

      <div className="max-w-6xl mx-auto px-4 py-12">
        <div className="flex flex-col lg:flex-row gap-8">
          {/* Sidebar Filters */}
          <div className="w-full lg:w-48">
            <div className="bg-card rounded-lg p-6 shadow-md border border-border">
              <h3 className="text-lg font-semibold text-foreground mb-4">Categories</h3>
              <div className="space-y-2">
                {categoriesList.map((cat) => (
                  <button
                    key={cat}
                    onClick={() => setSelectedCategory(cat)}
                    className={`w-full text-left px-3 py-2 rounded-md transition-colors ${selectedCategory === cat ? "bg-primary text-primary-foreground" : "text-foreground hover:bg-muted"
                      }`}
                  >
                    {cat}
                  </button>
                ))}
              </div>

              <h3 className="text-lg font-semibold text-foreground mt-8 mb-4">Sort By</h3>
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value)}
                className="w-full px-3 py-2 border border-border rounded-md bg-background text-foreground"
              >
                <option value="popular">Most Popular</option>
                <option value="price-low">Price: Low to High</option>
                <option value="price-high">Price: High to Low</option>
                <option value="newest">Newest Arrivals</option>
              </select>
            </div>
          </div>

          {/* Products Grid */}
          <div className="flex-1">
            {loading ? (
              <div className="flex justify-center py-20">
                <Loader2 className="w-10 h-10 animate-spin text-primary" />
              </div>
            ) : products.length === 0 ? (
              <div className="text-center py-20">
                <p className="text-lg text-muted-foreground">No products found.</p>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {products.map((product) => (
                  <div
                    key={product.id}
                    className="bg-card rounded-lg overflow-hidden shadow-md border border-border hover:shadow-lg transition-shadow"
                  >
                    <div className="relative overflow-hidden bg-muted h-64">
                      <img
                        src={product.image || "/placeholder.svg"}
                        alt={product.name}
                        className="w-full h-full object-cover hover:scale-110 transition-transform duration-300"
                      />
                      {product.badge && (
                        <div className="absolute top-3 left-3 bg-primary text-primary-foreground px-3 py-1 rounded-full text-xs font-semibold">
                          {product.badge}
                        </div>
                      )}
                      <button
                        onClick={() => toggleWishlist(product.id)}
                        className="absolute top-3 right-3 bg-white rounded-full p-2 shadow-md hover:bg-primary hover:text-primary-foreground transition-colors"
                      >
                        <Heart size={20} className={wishlist.includes(product.id) ? "fill-primary text-primary" : ""} />
                      </button>
                    </div>

                    <div className="p-4">
                      <p className="text-xs text-muted-foreground font-medium uppercase tracking-wide mb-1">
                        {product.category}
                      </p>
                      <h3 className="text-lg font-semibold text-foreground mb-2 truncate">{product.name}</h3>

                      <div className="flex items-center gap-2 mb-3">
                        <div className="flex items-center gap-1">
                          {[...Array(5)].map((_, i) => (
                            <span key={i} className={i < Math.floor(product.rating) ? "text-accent" : "text-muted"}>
                              ★
                            </span>
                          ))}
                        </div>
                        <span className="text-xs text-muted-foreground">({product.reviews})</span>
                      </div>

                      <div className="flex items-center gap-2 mb-4">
                        <span className="text-xl font-bold text-primary">₹{product.price}</span>
                        {product.originalPrice && (
                          <span className="text-sm text-muted-foreground line-through">₹{product.originalPrice}</span>
                        )}
                      </div>

                      <Link href={`/products/${product.id}`} className="w-full bg-primary text-primary-foreground py-2 rounded-md font-medium hover:bg-primary/90 transition-colors flex items-center justify-center gap-2">
                        <ShoppingCart size={18} />
                        View Details
                      </Link>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      <Footer />
    </div>
  )
}

export default function ProductsPage() {
  return (
    <Suspense fallback={<div className="min-h-screen flex items-center justify-center"><Loader2 className="animate-spin" /></div>}>
      <ProductsContent />
    </Suspense>
  )
}
